import 'dart:convert';
import 'dart:io';

import 'package:rsaas_core/rsaas_core.dart';
import 'package:test/test.dart';

/// Every vector in test/golden/*.json (generated by tool/gen_golden.py, an independent reference)
/// must be reproduced exactly. apps/api/test/golden.spec.ts runs the same files against the TS port.
void main() {
  final dir = Directory('test/golden');
  final files = dir.listSync().whereType<File>().where((f) => f.path.endsWith('.json')).toList()..sort((a, b) => a.path.compareTo(b.path));
  var count = 0;
  for (final f in files) {
    final vectors = (jsonDecode(f.readAsStringSync()) as List).cast<Map<String, Object?>>();
    group(f.uri.pathSegments.last, () {
      for (final v in vectors) {
        count++;
        test('${v['id']}: ${v['description']}', () {
          final lines = (v['lines']! as List).cast<Map<String, Object?>>().map(LineInput.fromJson).toList();
          final discount = Discount.fromJson(v['discount'] as Map<String, Object?>?);
          final expected = v['expected']! as Map<String, Object?>;
          if (expected.containsKey('error')) {
            expect(() => computeBill(lines, discount: discount, tipPaise: v['tipPaise']! as int),
                throwsA(isA<BillingError>().having((e) => e.code, 'code', expected['error'])));
            return;
          }
          final bill = computeBill(lines, discount: discount, tipPaise: v['tipPaise']! as int);
          final actual = Map<String, Object?>.from(bill.toJson());
          final exp = Map<String, Object?>.from(expected)..remove('payments');
          expect(jsonDecode(jsonEncode(actual)), equals(exp));
          // invariants that must hold for every bill
          expect(bill.roundOffPaise, inInclusiveRange(-49, 50));
          expect(bill.totalPaise % 100, 0);
          expect(bill.subtotalPaise - bill.discountPaise + bill.cgstPaise + bill.sgstPaise + bill.tipPaise + bill.roundOffPaise, bill.totalPaise);
          if (v['payments'] != null) {
            final pays = (v['payments']! as List).cast<Map<String, Object?>>().map(PaymentInput.fromJson).toList();
            final ep = expected['payments']! as Map<String, Object?>;
            if (ep.containsKey('error')) {
              expect(() => applyPayments(bill.totalPaise, pays), throwsA(isA<BillingError>().having((e) => e.code, 'code', ep['error'])));
            } else {
              expect(applyPayments(bill.totalPaise, pays).toJson(), equals(ep));
            }
          }
        });
      }
    });
  }
  test('has at least 30 golden vectors', () => expect(count, greaterThanOrEqualTo(30)));
}
